        for b_start, b_end in b_normalized:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # Check if b interval overlaps with current range
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap - keep the parts that don't overlap
